"""Compress browser screenshots for review; PNGs are regenerated by Playwright."""
from pathlib import Path
from PIL import Image, ImageOps
root=Path(__file__).resolve().parents[1]
for path in (root/'qa').glob('*.png'):
 im=Image.open(path);im.save(path.with_suffix('.webp'),quality=86);path.unlink()
thumb=root.parent/'games/thumbs/football.webp'
im=Image.open(root/'qa/1280-dribble.webp');ImageOps.fit(im,(640,480)).save(thumb,quality=86)
stale=root/'qa/video-source.txt'
if stale.exists():stale.unlink()
